final class Service {
 private $requests; private $stops; private $items; private $snapshots; private $handoffs; private $wpdb;
 public function __construct($wpdb=null){$this->wpdb=$wpdb?:$GLOBALS['wpdb'];$this->requests=new RequestRepository($this->wpdb);$this->stops=new StopRepository($this->wpdb);$this->items=new ItemRepository($this->wpdb);$this->snapshots=new SnapshotRepository($this->wpdb);$this->handoffs=new HandoffRepository($this->wpdb);}
 public function create_draft($data,$actor_id,$stops=array(),$items=array()){$actor=$this->actor($actor_id);if(is_wp_error($actor))return$actor;$owner=absint($actor_id);$data=$this->request_data($data);if(is_wp_error($data))return$data;$data=array_merge($data,array('owner_identity_id'=>$owner,'created_by_identity_id'=>$actor_id,'updated_by_identity_id'=>$actor_id,'status'=>'draft'));$this->begin();$request=$this->requests->create($data);if(is_wp_error($request))return$this->rollback($request);foreach($stops as$stop){$result=$this->add_stop($request->id(),$stop,$actor_id,false);if(is_wp_error($result))return$this->rollback($result);}foreach($items as$item){$result=$this->add_item($request->id(),$item,$actor_id,false);if(is_wp_error($result))return$this->rollback($result);}$this->commit();$this->activity('request_created','A shipping request draft was created.',$request->id(),$actor_id,array('public_id'=>$request->get('public_id')));return$this->load($request->id());}
 public function load($id,$include_archived=false){$request=$this->requests->find($id,$include_archived);if(!$request)return new \WP_Error('atlas_request_not_found',__('The shipping request was not found.','atlas-shipping'));$request->stops=$this->stops->for_request($id);$request->items=$this->items->for_request($id);$request->snapshots=$this->snapshots->for_request($id);$request->handoff=$this->handoffs->find_for_request($id);return$request;}
 public function coordinator_queue($actor){$valid=$this->coordinator($actor);if(is_wp_error($valid))return$valid;return$this->requests->listing(array('view'=>'upcoming','status'=>'submitted','sort'=>'updated','direction'=>'asc','page'=>1,'per_page'=>50));}
 public function handoff_workspace($public,$actor){$valid=$this->coordinator($actor);if(is_wp_error($valid))return$valid;return$this->view_request($public,$actor);}
 public function save_handoff($public,$data,$actor,$version){$valid=$this->coordinator($actor);if(is_wp_error($valid))return$valid;$r=$this->requests->find_by_public_id($public);if(!$r||'submitted'!==$r->get('status'))return new \WP_Error('atlas_handoff_state_invalid',__('Only submitted requests can be prepared for handoff.','atlas-shipping'));if(absint($r->get('row_version'))!==absint($version))return$this->conflict();$clean=$this->handoff_data($data);if(is_wp_error($clean))return$clean;if(!$this->handoffs->save($r->id(),$actor,$clean))return new \WP_Error('atlas_handoff_save_failed',__('The coordinator handoff could not be saved.','atlas-shipping'));$this->activity('handoff_updated','A coordinator handoff decision was saved.',$r->id(),$actor);return$this->load($r->id());}
 public function send_handoff($public,$data,$actor,$version){$valid=$this->coordinator($actor);if(is_wp_error($valid))return$valid;$r=$this->requests->find_by_public_id($public);if(!$r||'submitted'!==$r->get('status'))return new \WP_Error('atlas_handoff_state_invalid',__('Only submitted requests can be sent to the shipper.','atlas-shipping'));$clean=$this->handoff_data($data);if(is_wp_error($clean))return$clean;$this->begin();$locked=$this->wpdb->get_row($this->wpdb->prepare('SELECT status,row_version FROM '.$this->wpdb->prefix.'atlas_shipping_requests WHERE id=%d FOR UPDATE',$r->id()));if(!$locked||'submitted'!==$locked->status||absint($locked->row_version)!==absint($version))return$this->rollback($this->conflict());if(!$this->handoffs->save($r->id(),$actor,$clean))return$this->rollback(new \WP_Error('atlas_handoff_save_failed',__('The coordinator handoff could not be saved.','atlas-shipping')));$aggregate=$this->load($r->id());$payload=array('public_id'=>$r->get('public_id'),'request'=>$aggregate->to_array(),'stops'=>array_map(fn($v)=>$v->to_array(),$aggregate->stops),'items'=>array_map(fn($v)=>$v->to_array(),$aggregate->items),'handoff'=>$this->handoffs->find_for_request($r->id()));unset($payload['handoff']['id'],$payload['handoff']['snapshot_id']);$content=wp_json_encode($payload,JSON_UNESCAPED_SLASHES);$number=$this->snapshots->next_number_for_update($r->id());$snapshot=$this->snapshots->create(array('request_id'=>$r->id(),'snapshot_no'=>$number,'snapshot_type'=>'shipper_handoff','created_by_identity_id'=>absint($actor),'parent_snapshot_id'=>null,'reason'=>'Coordinator sent request to shipper.','content'=>$content,'content_hash'=>hash('sha256',$content)));if(is_wp_error($snapshot))return$this->rollback($snapshot);if(!$this->handoffs->mark_sent($r->id(),$snapshot->id()))return$this->rollback(new \WP_Error('atlas_handoff_link_failed',__('The handoff snapshot could not be linked.','atlas-shipping')));if(!$this->requests->update($r->id(),array('status'=>'sent_to_sh